const path = require("path");

function extension(nomFichier) {
  return path.extname(nomFichier);
}

function tva(prix) {
  return Math.round(prix * 0.18);
}

function ttc(prix) {
  return prix + tva(prix);
}

module.exports = { tva, ttc };

